// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address player, uint256 warp) public {
        vm.assume(player != address(0));
        vm.deal(player, 100 ether);

        vm.warp(warp);

        uint256 ticket = 10;
        vm.prank(player);
        uint256 before = address(c).balance;

        bool ok;
        try c.play{value: ticket}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok && c.pot() == 0) {
            assertTrue(address(c).balance <= before);
        } else {
            assertTrue(address(c).balance >= before);
        }
    }
}
